/**
 * Get translated peptide description
 * Falls back to English if translation not found
 */
export function getTranslatedDescription(description: string, language: Language): string {
  const translations = peptideDescriptionTranslations[description];
  if (translations) {
    return translations[language] || translations.en || description;
  }
  return description;
}
